--
-- Table structure for table `projects`
--

DROP TABLE IF EXISTS `projects`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `projects` (
  `project_id` varchar(36) NOT NULL,
  `project_name` varchar(100) NOT NULL,
  `project_description` text,
  `total_amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `amount_paid` decimal(10,2) NOT NULL DEFAULT '0.00',
  `amount_due` decimal(10,2) NOT NULL DEFAULT '0.00',
  `project_deadline` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `project_start_date` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `project_status` enum('ongoing','hold','done','planning','in_progress','completed','on_hold','cancelled') NOT NULL DEFAULT 'ongoing',
